    fn checkpoint_value(revision: u64) -> Value {
        serde_json::json!({
            "type": "projection_checkpoint",
            "persistence_revision": revision,
            "transcript": [],
            "tool_context": [],
        })
    }

    fn attach(
        store: &SessionProjectionStore,
        session_id: &str,
        revision: u64,
    ) -> SessionProjection {
        store
            .snapshot(session_id, revision, checkpoint_value(revision))
            .unwrap()
    }

    fn store(lease: Duration) -> SessionProjectionStore {
        let dir = tempdir().unwrap();
        // Keep the temporary directory alive for the process-long test by using
        // a database file whose open handle remains valid after unlink on Unix.
        SessionProjectionStore::open_with_config(
            &dir.path().join("projection.db"),
            1024 * 1024,
            lease,
        )
        .unwrap()
    }

    #[cfg(unix)]
