    let consult = longhouse_prep_for_turn(prompt.clone(), cwd.clone()).await;
    let guided_prompt = apply_longhouse_prep(&guided_prompt, consult.as_ref());

    // OCEAN-40 (Phase 2): for in-browser surfaces, fold the client-supplied
